select ok((select relrowsecurity from pg_class where oid='app_private.canonical_authority_revision_v1'::regclass),'RLS enabled');
select ok(not has_table_privilege('anon','app_private.canonical_authority_revision_v1','SELECT'),'anonymous cannot read');
select ok(not has_table_privilege('authenticated','app_private.canonical_authority_revision_v1','UPDATE'),'authenticated cannot write');
select ok(not has_table_privilege('service_role','app_private.canonical_authority_revision_v1','UPDATE'),'service cannot write');
select ok(not has_function_privilege('authenticated','app_private.bump_canonical_authority_revision_v1()','EXECUTE'),'no bump RPC grant');
select ok(not has_function_privilege('service_role','app_private.bump_canonical_authority_revision_v1()','EXECUTE'),'no service bump grant');
select ok((select prosecdef from pg_proc where oid='app_private.bump_canonical_authority_revision_v1()'::regprocedure),'internal trigger definer');
select ok((select proconfig @> array['search_path=pg_catalog'] from pg_proc where oid='app_private.bump_canonical_authority_revision_v1()'::regprocedure),'fixed search path');
select throws_ok($$update app_private.canonical_authority_revision_v1 set revision=revision+1$$,'42501','canonical_authority_revision_write_denied','direct bump forbidden');
select throws_ok($$delete from app_private.canonical_authority_revision_v1$$,'42501','canonical_authority_revision_write_denied','direct deletion forbidden');
select throws_ok($$truncate app_private.canonical_authority_revision_v1$$,'42501','canonical_authority_revision_write_denied','truncate forbidden');
select ok((select count(*)=25 from pg_trigger where tgname='canonical_authority_revision_changed' and tgenabled='A' and tgtype=60),'all 25 hooks cover insert/update/delete/truncate, including replication mode');

-- Statement-event/rollback coverage, including sources with no rows. Actual
-- populated-source mutations and concurrent commits live in the PG host suite.
create function pg_temp.revision_event(source regclass, operation text)
returns boolean language plpgsql as $$
declare before_revision bigint; changed boolean:=false; column_name text;
begin
 select revision into before_revision from app_private.canonical_authority_revision_v1;
 select attname into column_name from pg_attribute
 where attrelid=source and attnum>0 and not attisdropped and attgenerated='' order by attnum limit 1;
 begin
   if operation='update' then execute format('update %s set %I=%I where false',source,column_name,column_name);
   elsif operation='delete' then execute format('delete from %s where false',source);
   elsif operation='truncate' then execute format('truncate %s cascade',source);
   else raise exception 'unexpected operation'; end if;
   select revision>before_revision into changed from app_private.canonical_authority_revision_v1;
   raise division_by_zero;
 exception when division_by_zero then null;
 end;
 return changed and (select revision=before_revision from app_private.canonical_authority_revision_v1);
end;
$$;
